def make_palindrome(string: str) -> str:
    def is_palindrome(s: str) -> bool:
        return s == s[::-1]

    n = len(string)

    for k in range(n, -1, -1):
        if is_palindrome(string[k:]):
            return string + string[:k][::-1]

    return string

